#!/bin/bash  HeliosLM GitHub Push Script  set -e  REPO_DIR=/mnt/agents/output cd $REPO_DIR  echo  echo  HeliosLM GitHub Push  echo  ==========================  echo    echo  This script will push HeliosLM to your GitHub repository.  echo    read -p  GitHub username:  USERNAME  if [ -z $USERNAME ]; then   echo  Error: Username is required   exit 1 fi  read -p  Repository name [helioslm]:  REPO_NAME  REPO_NAME=${REPO_NAME:-helioslm}  read -sp  GitHub Personal Access Token (classic, with 'repo' scope):  TOKEN  echo    if [ -z $TOKEN ]; then   echo  Error: Token is required   exit 1 fi  REMOTE_URL=https://${TOKEN}@github.com/${USERNAME}/${REPO_NAME}.git  echo    echo  Step 1: Creating repository on GitHub...  HTTP_STATUS=$(curl -s -o /dev/null -w %{http_code} -H Authorization: token ${TOKEN} https://api.github.com/repos/${USERNAME}/${REPO_NAME})  if [ $HTTP_STATUS -eq 404 ]; then   curl -s -H Authorization: token ${TOKEN}     -H Accept: application/vnd.github.v3+json     https://api.github.com/user/repos     -d {name:${REPO_NAME},private:false,auto_init:false} > /dev/null   echo    Repository created: https://github.com/${USERNAME}/${REPO_NAME}  elif [ $HTTP_STATUS -eq 200 ]; then   echo    Repository exists, will force push  else   echo    Warning: Could not verify repository (HTTP $HTTP_STATUS)  fi  echo    echo  Step 2: Setting remote...  git remote remove origin 2>/dev/null || true git remote add origin $REMOTE_URL  echo    echo  Step 3: Pushing to GitHub...  git push -u origin main --force  echo    echo  ==========================  echo  Push complete!  echo    echo  Repository: https://github.com/${USERNAME}/${REPO_NAME}  echo  Files: $(git ls-files | wc -l)  echo  Commits: $(git rev-list --count HEAD)  echo  Size: $(du -sh .git | cut -f1)  echo    echo  Next steps:  echo  1. Visit https://github.com/${USERNAME}/${REPO_NAME}  echo  2. Add README description and topics  echo  3. Enable GitHub Actions if needed  echo  4. Configure branch protection for 'main'  